import { Component, Input, Output, EventEmitter } from '@angular/core';

interface StepChangedPayload {
  from: number;
  to: number;
}

interface CompletedPayload {
  profile: object;
}

interface AbandonedPayload {
  last_step: number;
}

interface ProfileData {
  name: string;
  email: string;
  phone: string;
}

@Component({
  selector: 'app-onboarding-wizard',
  standalone: true,
  template: `
    <div class="onboarding-wizard">
      <header class="wizard-header">
        <h2>Onboarding-Wizard</h2>
        <div class="meta">
          <span>resume_token: {{ resume_token }}</span>
          <span>total_steps: {{ total_steps }}</span>
          <span>current_step: {{ currentStep }}</span>
        </div>
      </header>

      <section class="wizard-body">
        <div *ngIf="currentStep === 1" class="step step-welcome">
          <h3>Willkommen</h3>
          <p>Begrüßung – starten Sie mit Ihrem Onboarding.</p>
        </div>

        <div *ngIf="currentStep === 2" class="step step-profile">
          <h3>Profil-Daten</h3>
          <label>
            <span>Name</span>
            <input type="text" [value]="profile.name" (input)="updateProfile('name', $any($event.target).value)" />
          </label>
          <label>
            <span>E-Mail</span>
            <input type="email" [value]="profile.email" (input)="updateProfile('email', $any($event.target).value)" />
          </label>
          <label>
            <span>Telefon</span>
            <input type="tel" [value]="profile.phone" (input)="updateProfile('phone', $any($event.target).value)" />
          </label>
        </div>

        <div *ngIf="currentStep === 3" class="step step-confirm">
          <h3>Bestätigung</h3>
          <p>Bitte überprüfen Sie Ihre Angaben:</p>
          <ul>
            <li><span>Name:</span> {{ profile.name }}</li>
            <li><span>E-Mail:</span> {{ profile.email }}</li>
            <li><span>Telefon:</span> {{ profile.phone }}</li>
          </ul>
        </div>
      </section>

      <footer class="wizard-footer">
        <button type="button" (click)="back()" [disabled]="currentStep <= 1">Zurück</button>
        <button type="button" (click)="next()" *ngIf="currentStep < total_steps" [disabled]="!isStepValid()">Weiter</button>
        <button type="button" (click)="finish()" *ngIf="currentStep === total_steps">Abschließen</button>
        <button type="button" (click)="abandon()">Abbrechen</button>
      </footer>
    </div>
  `,
  styles: [`
    .onboarding-wizard { display: flex; flex-direction: column; gap: 1rem; padding: 1rem; border: 1px solid #ccc; border-radius: 8px; font-family: sans-serif; }
    .wizard-header { display: flex; flex-direction: column; gap: 0.25rem; }
    .meta { display: flex; gap: 0.75rem; font-size: 0.85rem; color: #555; }
    .wizard-body { min-height: 120px; }
    .step { display: flex; flex-direction: column; gap: 0.5rem; }
    label { display: flex; flex-direction: column; gap: 0.25rem; }
    .wizard-footer { display: flex; justify-content: space-between; gap: 0.5rem; }
    button { padding: 0.5rem 1rem; cursor: pointer; }
    button[disabled] { cursor: not-allowed; opacity: 0.6; }
  `]
})
export class OnboardingWizardComponent {
  @Input() resume_token?: string;
  @Input() total_steps: number = 3;

  @Output() step_changed = new EventEmitter<StepChangedPayload>();
  @Output() completed = new EventEmitter<CompletedPayload>();
  @Output() abandoned = new EventEmitter<AbandonedPayload>();

  private readonly storageKey = 'onboarding-wizard-state';
  private readonly persistMs = 24 * 60 * 60 * 1000;

  currentStep: number = 1;
  profile: ProfileData = { name: '', email: '', phone: '' };

  constructor() {
    this.restoreState();
  }

  updateProfile(field: keyof ProfileData, value: string): void {
    this.profile = { ...this.profile, [field]: value };
    this.persistState();
  }

  isStepValid(): boolean {
    if (this.currentStep === 2) {
      return !!this.profile.name && !!this.profile.email;
    }
    return true;
  }

  next(): void {
    if (!this.isStepValid()) {
      return;
    }
    if (this.currentStep < this.total_steps) {
      const from = this.currentStep;
      const to = from + 1;
      this.currentStep = to;
      this.persistState();
      this.step_changed.emit({ from, to });
    }
  }

  back(): void {
    if (this.currentStep > 1) {
      const from = this.currentStep;
      const to = from - 1;
      this.currentStep = to;
      this.persistState();
      this.step_changed.emit({ from, to });
    }
  }

  finish(): void {
    this.clearState();
    this.completed.emit({ profile: { ...this.profile } });
  }

  abandon(): void {
    this.persistState();
    this.abandoned.emit({ last_step: this.currentStep });
  }

  private persistState(): void {
    try {
      const payload = {
        currentStep: this.currentStep,
        profile: this.profile,
        expiresAt: Date.now() + this.persistMs
      };
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem(this.storageKey, JSON.stringify(payload));
      }
    } catch {
      // ignore persistence errors
    }
  }

  private restoreState(): void {
    try {
      if (typeof localStorage === 'undefined') {
        return;
      }
      const raw = localStorage.getItem(this.storageKey);
      if (!raw) {
        return;
      }
      const parsed = JSON.parse(raw) as { currentStep: number; profile: ProfileData; expiresAt: number };
      if (!parsed || typeof parsed.expiresAt !== 'number' || parsed.expiresAt < Date.now()) {
        localStorage.removeItem(this.storageKey);
        return;
      }
      if (this.resume_token) {
        this.currentStep = parsed.currentStep;
        this.profile = parsed.profile;
      }
    } catch {
      // ignore restore errors
    }
  }

  private clearState(): void {
    try {
      if (typeof localStorage !== 'undefined') {
        localStorage.removeItem(this.storageKey);
      }
    } catch {
      // ignore
    }
  }
}
